@AccessControl.authorizationCheck: #MANDATORY
@EndUserText.label: 'Business Partner Details'
@Metadata.ignorePropagatedAnnotations: true
@Metadata.allowExtensions: true

@Search.searchable: true
define root view entity ZLH_C_BusinessPartner
  provider contract transactional_query
  as projection on ZLH_R_BusinessPartner
{
  key     SoldToParty,
          CustomerName,
          LastChangeTime,
          AuthorizationGroup,
          ETag,
          UserID,
          @ObjectModel.virtualElementCalculatedBy: 'ABAP:ZCL_LH_BP_CALC_EXIT'
  virtual MembershipCategory          : zlh_category_name,
          //          @ObjectModel.virtualElementCalculatedBy: 'ABAP:ZCL_LH_BP_CALC_EXIT'
          //  virtual MembershipStatus            : zlh_category_status,

          @ObjectModel.virtualElementCalculatedBy: 'ABAP:ZCL_LH_BP_CALC_EXIT'
  virtual TotalLoyaltyPointsAvailable : zlh_loyaltypoint,
          @ObjectModel.virtualElementCalculatedBy: 'ABAP:ZCL_LH_BP_CALC_EXIT'
  virtual TotalLoyaltyPointsRedeemed  : zlh_loyaltypoint,
          @ObjectModel.virtualElementCalculatedBy: 'ABAP:ZCL_LH_BP_CALC_EXIT'
  virtual LltyPtsAvailableCriticality : abap.int1,
          @ObjectModel.virtualElementCalculatedBy: 'ABAP:ZCL_LH_BP_CALC_EXIT'
  virtual LoyaltyMembershipCriticality: abap.int1,
          
//          @ObjectModel.virtualElementCalculatedBy: 'ABAP:ZCL_LH_BP_CALC_EXIT'
//   virtual UserType: zlh_usertype,
          //  _MemberShip._Category,
          _MemberShip.MembershipID as MemberShipID,
          _MemberShip.MemberSince,
//          @ObjectModel.text.element:[ 'StatusText' ]
//          @UI.textArrangement: #TEXT_FIRST
//          _MemberShip.MembershipStatus,
//          _MemberShip.StatusText,
          //          _MemberShip._StatusVH,
          _MemberShip.MembershipEndDate,
          /* Associations */
          _GiftCard     : redirected to composition child ZLH_C_GIFTCARD,
          _MemberShip   : redirected to composition child ZLH_C_Membership,
          _Transactions : redirected to composition child ZLH_C_TRANSACTIONS,
          _Category     : redirected to ZLH_C_CATEGORY
}
